#' @export
Variance <- function(
    data,
    X,
    CV = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("Variance requires jmvcore to be installed (restart may be required)")

    if ( ! missing(X)) X <- jmvcore::resolveQuo(jmvcore::enquo(X))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(X), X, NULL))


    options <- VarianceOptions$new(
        X = X,
        CV = CV)

    analysis <- VarianceClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

